-- MIS METAS DE AHORRO: esquema Supabase independiente
create extension if not exists pgcrypto;
create table if not exists public.savings_goals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null check(char_length(name) between 1 and 100), category text not null default 'other' check(category in ('car','education','home','vacation','purchase','other')), target_amount numeric(14,2) not null check(target_amount>0), target_date date, icon text, color text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.savings_contributions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, goal_id uuid not null references public.savings_goals(id) on delete cascade, amount numeric(14,2) not null check(amount>0), contribution_date date not null default current_date, note text, is_completed boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.savings_reminder_settings (user_id uuid primary key references auth.users(id) on delete cascade, enabled boolean not null default false, local_time time not null default '19:00', timezone text not null default 'America/Bogota', channel text not null default 'push', updated_at timestamptz not null default now());
create table if not exists public.savings_push_subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, endpoint text not null unique, p256dh text not null, auth_secret text not null, device_label text, created_at timestamptz not null default now(), last_seen_at timestamptz not null default now());
create index if not exists savings_goals_user_idx on public.savings_goals(user_id);
create index if not exists savings_contributions_user_date_idx on public.savings_contributions(user_id,contribution_date desc);
create index if not exists savings_contributions_goal_idx on public.savings_contributions(goal_id);
create index if not exists savings_push_user_idx on public.savings_push_subscriptions(user_id);
alter table public.savings_goals enable row level security; alter table public.savings_contributions enable row level security; alter table public.savings_reminder_settings enable row level security; alter table public.savings_push_subscriptions enable row level security;
drop policy if exists "Users manage their own savings goals" on public.savings_goals; create policy "Users manage their own savings goals" on public.savings_goals for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users manage their own savings contributions" on public.savings_contributions; create policy "Users manage their own savings contributions" on public.savings_contributions for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id and exists(select 1 from public.savings_goals g where g.id=goal_id and g.user_id=(select auth.uid())));
drop policy if exists "Users manage their own reminder settings" on public.savings_reminder_settings; create policy "Users manage their own reminder settings" on public.savings_reminder_settings for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Users manage their own push subscriptions" on public.savings_push_subscriptions; create policy "Users manage their own push subscriptions" on public.savings_push_subscriptions for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
grant select,insert,update,delete on public.savings_goals,savings_contributions,savings_reminder_settings,savings_push_subscriptions to authenticated;
